import{_ as l,a0 as p,w as a,s as u,I as e,x as t,a1 as n,A as i,ao as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"如何在 Ubuntu 15.04 / CentOS 7 上安裝 Android Studio | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Ubuntu 15.04 / CentOS 7 上安裝 Android Studio | LCTT (201512) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Ubuntu 15.04 / CentOS 7 上安裝 Android Studio | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Ubuntu 15.04 / CentOS 7 上安裝 Android Studio | LCTT (201512) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201512/20151123 How to install Android Studio on Ubuntu 15.04 or CentOS 7","title":"如何在 Ubuntu 15.04 / CentOS 7 上安裝 Android Studio","tag":"201512","desc":""},"relativePath":"201512/20151123 How to install Android Studio on Ubuntu 15.04 or CentOS 7.md","filePath":"[post].md"}'),s={name:"201512/20151123 How to install Android Studio on Ubuntu 15.04 or CentOS 7.md"};function m(S,o,b,A,g,T){const d=p("Link");return a(),u("div",null,[o[22]||(o[22]=e("h1",{id:"如何在-ubuntu-15-04-centos-7-上安裝-android-studio",tabindex:"-1"},[t("如何在 Ubuntu 15.04 / CentOS 7 上安裝 Android Studio "),e("a",{class:"header-anchor",href:"#如何在-ubuntu-15-04-centos-7-上安裝-android-studio","aria-label":"Permalink to “如何在 Ubuntu 15.04 / CentOS 7 上安裝 Android Studio”"},"​")],-1)),e("p",null,[o[1]||(o[1]=t("隨着最近幾年智能手機的進步，安卓成為了最大的手機平台之一，在開發安卓應用中所用到的所有工具也都可以免費得到。Android Studio 是基於 ",-1)),n(d,{href:"https://www.jetbrains.com/idea/"},{default:i(()=>[...o[0]||(o[0]=[t("IntelliJ IDEA",-1)])]),_:1}),o[2]||(o[2]=t(" 用於開發安卓應用的集成開發環境（IDE）。它是 Google 2014 年發佈的免費開源軟件，繼 Eclipse 之後成為主要的 IDE。",-1))]),o[23]||(o[23]=r(`<p>在這篇文章，我們一起來學習如何在 Ubuntu 15.04 和 CentOS 7 上安裝 Android Studio。</p><h3 id="在-ubuntu-15-04-上安裝" tabindex="-1">在 Ubuntu 15.04 上安裝 <a class="header-anchor" href="#在-ubuntu-15-04-上安裝" aria-label="Permalink to “在 Ubuntu 15.04 上安裝”">​</a></h3><p>我們可以用兩種方式安裝 Android Studio。第一種是配置所需的庫然後再安裝它；另一種是從 Android 官方網站下載然後在本地編譯安裝。在下面的例子中，我們會使用命令列設置庫並安裝它。在繼續下一步之前，我們需要確保我們已經安裝了 JDK 1.6 或者更新版本。</p><p>這裏，我打算安裝 JDK 1.8。</p><pre><code>$ sudo add-apt-repository ppa:webupd8team/java
$ sudo apt-get update
$ sudo apt-get install oracle-java8-installer oracle-java8-set-default
</code></pre><p>驗證 java 是否安裝成功：</p><pre><code>poornima@poornima-Lenovo:~$ java  -version
</code></pre><p>現在，設置安裝 Android Studio 需要的庫</p><pre><code>$ sudo apt-add-repository ppa:paolorotolo/android-studio
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/11/Android-studio-repo.png" alt="Android-Studio-repo"></p><pre><code>$ sudo apt-get update
$ sudo apt-get install android-studio
</code></pre><p>上面的安裝命令會在 /opt 目錄下面安裝 Android Studio。</p><p>現在，運行下面的命令啓動安裝嚮導：</p><pre><code>$ /opt/android-studio/bin/studio.sh
</code></pre><p>這會激活安裝窗口。下面的截圖展示了安裝 Android Studio 的過程。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/11/Studio-setup.png" alt="安裝 Android Studio"></p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/11/Install-type.png" alt="安裝類型"></p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/11/Emulator-settings.png" alt="設置模擬器"></p><p>你點擊了 Finish 按鈕之後，就會顯示同意協議頁面。當你接受協議之後，它就開始下載需要的組件。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/11/Download.png" alt="下載組件"></p><p>這一步完成之後就結束了 Android Studio 的安裝。當你重啓 Android Studio 時，你會看到下面的歡迎界面，從這裏你可以開始用 Android Studio 工作了。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/11/Welcome-screen.png" alt="歡迎界面"></p><h3 id="在-centos-7-上安裝" tabindex="-1">在 CentOS 7 上安裝 <a class="header-anchor" href="#在-centos-7-上安裝" aria-label="Permalink to “在 CentOS 7 上安裝”">​</a></h3>`,23)),e("p",null,[o[4]||(o[4]=t("現在再讓我們來看看如何在 CentOS 7 上安裝 Android Studio。這裏你同樣需要安裝 JDK 1.6 或者更新版本。如果你不是 root 用户，記得在命令前面使用 ‘sudo’。你可以下載",-1)),n(d,{href:"http://www.oracle.com/technetwork/java/javase/downloads/jdk8-downloads-2133151.html"},{default:i(()=>[...o[3]||(o[3]=[t("最新版本",-1)])]),_:1}),o[5]||(o[5]=t("的 JDK。如果你已經安裝了一個比較舊的版本，在安裝新的版本之前你需要先卸載舊版本。在下面的例子中，我會通過下載需要的 rpm 包安裝 JDK 1.8.0_65。",-1))]),o[24]||(o[24]=r(`<pre><code>[root@li1260-39 ~]# rpm -ivh jdk-8u65-linux-x64.rpm
Preparing... ################################# [100%]
Updating / installing...
1:jdk1.8.0_65-2000:1.8.0_65-fcs ################################# [100%]
Unpacking JAR files...
tools.jar...
plugin.jar...
javaws.jar...
deploy.jar...
rt.jar...
jsse.jar...
charsets.jar...
localedata.jar...
jfxrt.jar...
</code></pre><p>如果沒有正確設置 Java 路徑，你會看到錯誤信息。因此，設置正確的路徑：</p><pre><code>export JAVA_HOME=/usr/java/jdk1.8.0_25/
export PATH=$PATH:$JAVA_HOME
</code></pre><p>檢查是否安裝了正確的版本：</p><pre><code>[root@li1260-39 ~]# java -version
java version &quot;1.8.0_65&quot;
Java(TM) SE Runtime Environment (build 1.8.0_65-b17)
Java HotSpot(TM) 64-Bit Server VM (build 25.65-b01, mixed mode)
</code></pre><p>如果你安裝 Android Studio 的時候看到任何類似 “unable-to-run-mksdcard-sdk-tool:” 的錯誤信息，你可能要在 CentOS 7 64 位系統中安裝以下軟件包：</p><ul><li>glibc.i686</li><li>glibc-devel.i686</li><li>libstdc++.i686</li><li>zlib-devel.i686</li><li>ncurses-devel.i686</li><li>libX11-devel.i686</li><li>libXrender.i686</li><li>libXrandr.i686</li></ul>`,7)),e("p",null,[o[7]||(o[7]=t("通過從 ",-1)),n(d,{href:"http://developer.android.com/sdk/index.html"},{default:i(()=>[...o[6]||(o[6]=[t("Android 網站",-1)])]),_:1}),o[8]||(o[8]=t(" 下載 IDE 文件然後解壓安裝 studio 也是一樣的。",-1))]),o[25]||(o[25]=r(`<pre><code>[root@li1260-39 tmp]# unzip android-studio-ide-141.2343393-linux.zip
</code></pre><p>移動 android-studio 目錄到 /opt 目錄</p><pre><code>[root@li1260-39 tmp]# mv /tmp/android-studio/ /opt/
</code></pre><p>需要的話你可以創建一個到 studio 可執行文件的符號鏈接用於快速啓動。</p><pre><code>[root@li1260-39 tmp]# ln -s /opt/android-studio/bin/studio.sh /usr/local/bin/android-studio
</code></pre><p>現在在終端中啓動 studio：</p><pre><code>[root@localhost ~]#studio
</code></pre><p>之後用於完成安裝的截圖和前面 Ubuntu 安裝過程中的是一樣的。安裝完成後，你就可以開始開發你自己的 Android 應用了。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>雖然發佈不到一年，但是 Android Studio 已經替代 Eclipse 成為了 Android 的開發最主要的 IDE。它是唯一能支持 Google 之後將要提供的 Android SDK 和其它 Android 特性的官方 IDE 工具。那麼，你還在等什麼呢？趕快安裝 Android Studio 來體驗開發 Android 應用的樂趣吧。</p><hr>`,11)),e("p",null,[o[10]||(o[10]=t("via: ",-1)),n(d,{href:"http://linoxide.com/tools/install-android-studio-ubuntu-15-04-centos-7/"},{default:i(()=>[...o[9]||(o[9]=[t("http://linoxide.com/tools/install-android-studio-ubuntu-15-04-centos-7/",-1)])]),_:1})]),e("p",null,[o[14]||(o[14]=t("作者：",-1)),n(d,{href:"http://linoxide.com/author/bnpoornima/"},{default:i(()=>[...o[11]||(o[11]=[t("B N Poornima",-1)])]),_:1}),o[15]||(o[15]=t(" 譯者：",-1)),n(d,{href:"http://mutouxiaogui.cn/blog/"},{default:i(()=>[...o[12]||(o[12]=[t("ictlyh",-1)])]),_:1}),o[16]||(o[16]=t(" 校對：",-1)),n(d,{href:"https://github.com/carolinewuyan"},{default:i(()=>[...o[13]||(o[13]=[t("Caroline",-1)])]),_:1})]),e("p",null,[o[19]||(o[19]=t("本文由 ",-1)),n(d,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...o[17]||(o[17]=[t("LCTT",-1)])]),_:1}),o[20]||(o[20]=t(" 原創編譯，",-1)),n(d,{href:"https://linux.cn/"},{default:i(()=>[...o[18]||(o[18]=[t("Linux中國",-1)])]),_:1}),o[21]||(o[21]=t(" 榮譽推出",-1))])])}const v=l(s,[["render",m]]);export{x as __pageData,v as default};
